print(f"Triangle constraints: {len(triangle_constraints)}")

# No 4-cycles: we can encode them more efficiently
# For each 4 distinct vertices, there are 3 possible 4-cycles (up to isomorphism)
# But we can use: for each i<j<k<l, we forbid all 3 possible 4-cycles
c4_constraints = []
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            for l in range(k+1, n):
                # 3 possible 4-cycles on these 4 vertices:
                # i-j-k-l-i, i-j-l-k-i, i-k-j-l-i
                c4_constraints.append(
                    z3.Not(z3.And(get_edge(i,j), get_edge(j,k), get_edge(k,l), get_edge(l,i)))
                )
                c4_constraints.append(
                    z3.Not(z3.And(get_edge(i,j), get_edge(j,l), get_edge(l,k), get_edge(k,i)))
                )
                c4_constraints.append(
                    z3.Not(z3.And(get_edge(i,k), get_edge(k,j), get_edge(j,l), get_edge(l,i)))
                )

print(f"C4 constraints: {len(c4_constraints)}")

# No 5-cycles
c5_constraints = []
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            for l in range(k+1, n):
                for m in range(l+1, n):
                    # There are 12 possible 5-cycles on 5 vertices
                    # But we can just forbid all 12
                    verts = [i, j, k, l, m]
                    # Generate all permutations that are cycles (up to rotation and reversal)
                    # For 5 vertices, there are 4!/2 = 12 distinct cycles
                    import itertools
                    for perm in itertools.permutations(verts):
                        # Only consider cycles starting with the smallest element
                        if perm[0] != min(perm):
                            continue
                        # And ensure the second element is smaller than the last (to avoid reversals)
                        if perm[1] > perm[-1]:
                            continue
                        edge_vars = [get_edge(perm[idx], perm[(idx+1)%5]) for idx in range(5)]
                        c5_constraints.append(z3.Not(z3.And(*edge_vars)))

print(f"C5 constraints: {len(c5_constraints)}")

