import z3
import time
from collections import defaultdict, deque

n = 23
min_deg = 3
max_deg = 7
girth = 7

# Create boolean variables for edges
edges = {}
for i in range(n):
    for j in range(i+1, n):
        edges[(i,j)] = z3.Bool(f"e_{i}_{j}")

def get_edge(i, j):
    if i < j:
        return edges[(i,j)]
    else:
        return edges[(j,i)]

# Degree constraints
degree_constraints = []
for i in range(n):
    incident = [get_edge(i, j) for j in range(n) if j != i]
    degree_constraints.append(z3.AtLeast(*incident, min_deg))
    degree_constraints.append(z3.AtMost(*incident, max_deg))

#encoding: for each vertex, we can use cardinality constraints
# Let's also add triangle constraints directly
triangle_constraints = []
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            triangle_constraints.append(
                z3.Not(z3.And(get_edge(i,j), get_edge(j,k), get_edge(k,i)))
            )

print(f"Triangle constraints: {len(triangle_constraints)}")

# For 4-cycles, 5-cycles, 6-cycles, we'll use lazy approach
solver = z3.Solver()
solver.add(degree_constraints)
solver.add(triangle_constraints)

print("Starting solve with lazy constraints...")
start = time.time()

def extract_graph(model):
    adj = defaultdict(set)
    for (i,j), var in edges.items():
        # Use model[var] which returns a BoolRef that we can check
        val = model[var]
        if val is not None and z3.is_true(val):
            adj[i].add(j)
            adj[j].add(i)
    return adj

def find_shortest_cycle(adj):
    shortest = float('inf')
    shortest_cycle = None
    for start in range(n):
        parent = {start: -1}
        dist = {start: 0}
        q = deque([start])
        while q:
            v = q.popleft()
            for u in adj[v]:
                if u not in dist:
                    dist[u] = dist[v] + 1
                    parent[u] = v
                    q.append(u)
                elif u != parent.get(v, -1):
                    cycle_len = dist[v] + dist[u] + 1
                    if cycle_len < shortest:
                        shortest = cycle_len
                        # Reconstruct
                        cycle = []
                        cur = v
                        while cur != -1:
                            cycle.append(cur)
                            cur = parent.get(cur, -1)
                        cur = u
                        while cur != -1:
                            cycle.append(cur)
                            cur = parent.get(cur, -1)
                        shortest_cycle = cycle
    return shortest, shortest_cycle

iteration = 0
while True:
    iteration += 1
    print(f"Iteration {iteration}: solving...")
    result = solver.check()
    if result == z3.unsat:
        print("UNSAT")
        break

    model = solver.model()
    adj = extract_graph(model)

    # Check degrees
    ok = True
    for v in range(n):
        if len(adj[v]) < min_deg or len(adj[v]) > max_deg:
            print(f"Degree violation at {v}: {len(adj[v])}")
            ok = False
    if not ok:
        break

    g, cycle = find_shortest_cycle(adj)
    print(f"Shortest cycle: {g}")

    if g >= girth:
        print(f"Found graph with girth {g}!")
        edge_list = []
        for i in range(n):
            for j in range(i+1, n):
                if j in adj[i]:
                    edge_list.append((i,j))
        print(f"Edges: {edge_list}")
        print(f"Number of edges: {len(edge_list)}")
        break

    # Add constraint to forbid this cycle
    if cycle:
        # Get unique vertices in order
        seen = set()
        unique_cycle = []
        for v in cycle:
            if v not in seen:
                seen.add(v)
                unique_cycle.append(v)

        L = len(unique_cycle)
        print(f"Cycle length: {L}, vertices: {unique_cycle}")

        edge_vars = []
        for idx in range(L):
            u = unique_cycle[idx]
            v = unique_cycle[(idx+1) % L]
            edge_vars.append(get_edge(u, v))
        solver.add(z3.Not(z3.And(*edge_vars)))

    if iteration > 200:
        print("Too many iterations")
        break

print(f"Time: {time.time() - start:.2f}s")
